import java.util.Objects;

class Rational {

    private final int numerator;
    private final int denominator;

    Rational(int numerator, int denominator) {
        if (denominator == 0) {
            throw new IllegalArgumentException("Denominator must not be zero.");
        }

        int gcd = gcd(Math.abs(numerator), Math.abs(denominator));
        int n = numerator / gcd;
        int d = denominator / gcd;

        if (d < 0) {
            n = -n;
            d = -d;
        }

        this.numerator = n;
        this.denominator = d;
    }

    int getNumerator() {
        return numerator;
    }

    int getDenominator() {
        return denominator;
    }

    Rational add(Rational other) {
        return new Rational(numerator * other.denominator + other.numerator * denominator,
                denominator * other.denominator);
    }

    Rational subtract(Rational other) {
        return new Rational(numerator * other.denominator - other.numerator * denominator,
                denominator * other.denominator);
    }

    Rational multiply(Rational other) {
        return new Rational(numerator * other.numerator, denominator * other.denominator);
    }

    Rational divide(Rational other) {
        return new Rational(numerator * other.denominator, denominator * other.numerator);
    }

    Rational abs() {
        return new Rational(Math.abs(numerator), Math.abs(denominator));
    }

    Rational pow(int power) {
        if (power >= 0) {
            return new Rational(integerPow(numerator, power), integerPow(denominator, power));
        }

        return new Rational(integerPow(denominator, -power), integerPow(numerator, -power));
    }

    double exp(double exponent) {
        return Math.pow(exponent, (double) numerator / denominator);
    }

    @Override
    public String toString() {
        return String.format("%d/%d", this.getNumerator(), this.getDenominator());
    }

    @Override
    public boolean equals(Object obj) {
        if (obj instanceof Rational other) {
            return this.getNumerator() == other.getNumerator()
                    && this.getDenominator() == other.getDenominator();
        }

        return false;
    }

    @Override
    public int hashCode() {
        return Objects.hash(this.getNumerator(), this.getDenominator());
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a == 0 ? 1 : a;
    }

    private static int integerPow(int base, int exponent) {
        int result = 1;
        for (int i = 0; i < exponent; i++) {
            result *= base;
        }
        return result;
    }
}

